/**
 * citations.mjs — are the artifact's `path:start-end` citations readable?
 *
 * Its own module, and deliberately free of side effects: `gen-verification.mjs` is a script that
 * writes `verification.json` when imported, so a control cannot import the rule from there without
 * regenerating the tree. Keeping the rule here is what makes every branch of it watchable.
 */
/**
 * Every `path:start-end` citation in the artifact must point at lines that exist.
 *
 * `--check` compared the generated bytes and nothing else, so a citation could name a range past the
 * end of its file — or a file that had since been deleted — and the gate stayed green. A citation
 * nobody can follow is not evidence, and being followable is this artifact's whole purpose: it is
 * what the platform pages and the verification dashboard cite.
 *
 * Walks the generated data rather than checking at the point each ref is built, so a range reaching
 * the artifact by any route is validated — including one introduced by a later hand edit, which the
 * generator's own arithmetic cannot cover.
 *
 * Pure, and takes its file reader as a parameter, so every branch below can be watched to fail
 * without a fixture repository: see `verification-guardrails.test.ts`.
 *
 * @param {unknown} data the generated artifact
 * @param {(file: string) => string | null} readFile source text, or null if the file is gone
 * @returns {string[]} one message per unreadable citation
 */
export function unreadableCitations(data, readFile) {
  const RANGED_REF = /^([^\s:]+):(\d+)-(\d+)$/;
  const out = [];
  const counts = new Map();
  const lineCountOf = (file) => {
    if (!counts.has(file)) {
      const text = readFile(file);
      counts.set(file, text === null ? null : text.endsWith("\n") ? text.split("\n").length - 1 : text.split("\n").length);
    }
    return counts.get(file);
  };
  const seen = new Set();
  const walk = (node) => {
    if (Array.isArray(node)) return void node.forEach(walk);
    if (node && typeof node === "object") return void Object.values(node).forEach(walk);
    if (typeof node !== "string" || seen.has(node)) return;
    seen.add(node);
    const m = node.match(RANGED_REF);
    if (!m) return;
    const [, file, startStr, endStr] = m;
    const start = Number(startStr);
    const end = Number(endStr);
    const total = lineCountOf(file);
    if (total === null) {
      out.push(`${node} cites a file that does not exist, so the evidence cannot be read.`);
    } else if (start < 1 || end < start) {
      out.push(`${node} is not a line range that can be read (${file} has ${total} line(s)).`);
    } else if (end > total) {
      out.push(
        `${node} cites line ${end}, but ${file} has ${total} line(s). A citation nobody can follow is ` +
          `not evidence — and a range past the end of a file is how an off-by-one in the generator ` +
          `stayed invisible through every green run of this gate.`,
      );
    }
  };
  walk(data);
  return out;
}

